package com.hs.jxc.it;

import static org.assertj.core.api.Assertions.*;
import static org.mockito.Mockito.*;
import static org.mockito.ArgumentMatchers.*;
import com.hs.jxc.pur.*;
import com.hs.jxc.md.api.ProductImageApi;
import com.hs.jxc.common.api.*;
import java.util.*;
import org.junit.jupiter.api.*;
import org.springframework.beans.factory.annotation.Autowired;

class ProductImageIT extends PurchaseImportFixture {
    @Autowired PurchaseImportPhotoService photos;
    @Autowired ProductImageApi images;
    @Autowired PurchaseImportProductService review;
    @BeforeEach void imagePermissions(){owner.update("UPDATE sys_role SET permissions=permissions||'[\"md:product:view\",\"md:product:edit\"]'::jsonb WHERE id=801");}
    Map<String,Object> withPhoto(){return withPhoto(photoDocument());}
    Map<String,Object> withPhoto(Map<String,Object> doc){
        var b=upload(UUID.randomUUID().toString());doReturn(doc).when(parser).parse(any(),anyString(),anyLong(),anyString(),isNull());tasks.execute(101,task(b));var saved=imports.get(actor,id(b));var row=rows(saved).getFirst();review.decide(actor,id(b),((Number)row.get("id")).longValue(),Map.of("version",1,"decision","EXISTING","productId",501,"unit","PCS"));return imports.get(actor,id(b));
    }
    long rowId(Map<String,Object>b){return ((Number)rows(b).getFirst().get("id")).longValue();}
    long imageId(Map<String,Object>b){return owner.queryForObject("SELECT i.id FROM pur_order_import_image i JOIN pur_order_import_source s ON s.country_id=i.country_id AND s.id=i.source_id WHERE s.batch_id=?",Long.class,id(b));}
    Map<String,Object> confirmedPhoto(){return confirmedPhoto(photoDocument());}
    Map<String,Object> confirmedPhoto(Map<String,Object> doc){var b=withPhoto(doc);imports.associate(actor,id(b),rowId(b),imageId(b),Map.of("version",2,"association","CONFIRMED"));return imports.get(actor,id(b));}
    Map<String,Object> publish(Map<String,Object>b,String key){return photos.publish(actor,id(b),rowId(b),Map.of("version",rows(b).getFirst().get("version"),"confirmOwnership",true,"imageIds",List.of(imageId(b))),key);}
    @Test void unconfirmedAnchorCannotPublishToTheRealProductGallery(){var b=withPhoto();assertThatThrownBy(()->publish(b,UUID.randomUUID().toString())).isInstanceOf(ApiException.class);assertThat(owner.queryForObject("SELECT count(*) FROM md_product_image",Integer.class)).isZero();assertThat(images.gallery(actor).get("status")).isEqualTo("EMPTY");}
    @Test void explicitOwnershipReusesAssetAndRepeatedPublishDoesNotDuplicateRelationsOrFeatures(){var b=confirmedPhoto();String key=UUID.randomUUID().toString();var one=publish(b,key);publish(b,key);assertThat(owner.queryForObject("SELECT count(*) FROM md_product_image",Integer.class)).isEqualTo(1);assertThat(owner.queryForObject("SELECT count(*) FROM image_feature",Integer.class)).isEqualTo(1);assertThat(owner.queryForObject("SELECT count(*) FROM sys_attachment_link",Integer.class)).isZero();assertThat(images.list(actor,501)).hasSize(1);assertThat(rows(imports.get(actor,id(b))).getFirst().get("readiness")).isEqualTo("READY");assertThat(one.get("taskIds")).isNotNull();assertThatThrownBy(()->imports.associate(actor,id(b),rowId(b),imageId(b),Map.of("version",3,"association","REJECTED"))).isInstanceOf(ApiException.class).extracting("status").isEqualTo(409);}
    @Test void modelFailureIsExplicitAndDoesNotChangePurchaseReadiness(){var b=confirmedPhoto();var result=publish(b,UUID.randomUUID().toString());doThrow(new ApiException(503,"MODEL_UNAVAILABLE","本地模型不可用")).when(parser).embed(any(),anyString(),anyLong(),anyString());UUID task=UUID.fromString(((List<?>)result.get("taskIds")).getFirst().toString());tasks.execute(101,task);assertThat(tasks.get(actor,task)).containsEntry("status","FAILED").containsEntry("errorCode","MODEL_UNAVAILABLE");assertThat(images.list(actor,501).getFirst()).containsEntry("featureStatus","FAILED");assertThat(rows(imports.get(actor,id(b))).getFirst().get("readiness")).isEqualTo("READY");assertThat(owner.queryForObject("SELECT count(*) FROM md_product_image",Integer.class)).isEqualTo(1);}
    @Test void fakeProductCannotReceiveARealPhoto(){var b=confirmedPhoto();owner.update("UPDATE pur_order_import SET matched_product_id=999999 WHERE id=?",rowId(b));assertThatThrownBy(()->publish(b,UUID.randomUUID().toString())).isInstanceOf(ApiException.class);assertThat(owner.queryForObject("SELECT count(*) FROM md_product_image",Integer.class)).isZero();}


    @Test void failedIndexKeepsFeatureAndRetryDoesNotCallTheModelAgain(){var b=confirmedPhoto();var published=publish(b,UUID.randomUUID().toString());UUID task=UUID.fromString(((List<?>)published.get("taskIds")).getFirst().toString());doReturn(vector()).when(parser).embed(any(),anyString(),anyLong(),anyString());doThrow(new ApiException(503,"INDEX_UNAVAILABLE","索引服务不可用")).when(parser).index(any(),anyString(),anyMap());tasks.execute(101,task);assertThat(images.list(actor,501).getFirst()).containsEntry("featureStatus","READY").containsEntry("indexStatus","FAILED");assertThat(images.gallery(actor).get("status")).isEqualTo("FAILED");tasks.retry(actor,task,UUID.randomUUID().toString(),null);doAnswer(call->indexResult(call.getArgument(2))).when(parser).index(any(),anyString(),anyMap());tasks.execute(101,task);assertThat(tasks.get(actor,task)).containsEntry("status","SUCCEEDED");assertThat(images.gallery(actor).get("status")).isEqualTo("READY");verify(parser,times(1)).embed(any(),anyString(),anyLong(),anyString());assertThat(owner.queryForObject("SELECT count(*) FROM image_feature",Integer.class)).isEqualTo(1);assertThat(owner.queryForObject("SELECT count(*) FROM md_image_index_generation WHERE active",Integer.class)).isEqualTo(1);assertThat(rows(imports.get(actor,id(b))).getFirst().get("readiness")).isEqualTo("READY");}
    @Test void deletedPhotoIsFilteredFromOldStableIndexAndFakeFeatureIsRejected(){var b=confirmedPhoto();var published=publish(b,UUID.randomUUID().toString());UUID task=UUID.fromString(((List<?>)published.get("taskIds")).getFirst().toString());doReturn(vector()).when(parser).embed(any(),anyString(),anyLong(),anyString());doAnswer(call->indexResult(call.getArgument(2))).when(parser).index(any(),anyString(),anyMap());tasks.execute(101,task);String generation=task.toString().replace("-","");long feature=owner.queryForObject("SELECT id FROM image_feature",Long.class);assertThat(images.resolveHits(actor,generation,List.of(Map.of("featureId",feature,"score",0.9)))).hasSize(1);assertThatThrownBy(()->images.resolveHits(actor,generation,List.of(Map.of("featureId",feature+1,"score",0.9)))).isInstanceOf(ApiException.class);owner.update("UPDATE md_product_image SET status='DELETED'");assertThat(images.resolveHits(actor,generation,List.of(Map.of("featureId",feature,"score",0.9)))).isEmpty();assertThat(images.gallery(actor).get("status")).isEqualTo("EMPTY");}
    @Test void invalidZeroVectorFailsBeforeAnyIndexIsPublished(){var b=confirmedPhoto();var published=publish(b,UUID.randomUUID().toString());UUID task=UUID.fromString(((List<?>)published.get("taskIds")).getFirst().toString());var invalid=new LinkedHashMap<>(vector());invalid.put("data",Base64.getEncoder().encodeToString(new byte[384*4]));doReturn(invalid).when(parser).embed(any(),anyString(),anyLong(),anyString());tasks.execute(101,task);assertThat(tasks.get(actor,task)).containsEntry("status","FAILED");assertThat(images.list(actor,501).getFirst()).containsEntry("featureStatus","FAILED");assertThat(owner.queryForObject("SELECT count(*) FROM md_image_index_generation",Integer.class)).isZero();}

    @Test void sameAssetExplicitlyLinkedToAnotherSpecificationReusesOneFeature(){var b=confirmedPhoto();publish(b,UUID.randomUUID().toString());owner.update("INSERT INTO md_product(id,product_code,name,base_unit,spec) VALUES(502,'SECOND','第二规格','PCS','M')");owner.update("INSERT INTO md_country_sku(country_id,product_id,status) VALUES(101,502,'ENABLED')");long asset=owner.queryForObject("SELECT attachment_id FROM pur_order_import_image",Long.class);images.link(actor,502,asset);assertThat(owner.queryForObject("SELECT count(*) FROM md_product_image",Integer.class)).isEqualTo(2);assertThat(owner.queryForObject("SELECT count(*) FROM image_feature",Integer.class)).isEqualTo(1);assertThat(images.list(actor,501)).hasSize(1);assertThat(images.list(actor,502)).hasSize(1);}
    @Test void imageTaskCredentialCannotReadAnotherAssetAndExpiresAfterFailure(){var b=confirmedPhoto();var published=publish(b,UUID.randomUUID().toString());UUID task=UUID.fromString(((List<?>)published.get("taskIds")).getFirst().toString());var captured=new java.util.concurrent.atomic.AtomicReference<String>();var assetId=new java.util.concurrent.atomic.AtomicLong();doAnswer(call->{String credential=call.getArgument(1);long asset=call.getArgument(2);captured.set(credential);assetId.set(asset);assertThat(tasks.taskAsset(task,asset,credential).bytes()).isNotEmpty();assertThatThrownBy(()->tasks.taskAsset(task,asset+1,credential)).isInstanceOf(ApiException.class).extracting("status").isEqualTo(403);throw new ApiException(503,"MODEL_UNAVAILABLE","受限资产已验证，模型未启用");}).when(parser).embed(any(),anyString(),anyLong(),anyString());tasks.execute(101,task);assertThat(tasks.get(actor,task)).containsEntry("errorCode","MODEL_UNAVAILABLE");assertThatThrownBy(()->tasks.taskAsset(task,assetId.get(),captured.get())).isInstanceOf(ApiException.class).extracting("status").isEqualTo(403);}
    @Test void actualPythonFaissBridgePublishesARealIndexWithoutRunningPhotoInference()throws Exception{String python=System.getProperty("jxc.test.purchase-python");Assumptions.assumeTrue(python!=null,"显式选择解释器才运行真实Faiss桥接；特征使用确定性夹具，不冒充照片准确率");var b=confirmedPhoto();var published=publish(b,UUID.randomUUID().toString());UUID task=UUID.fromString(((List<?>)published.get("taskIds")).getFirst().toString());doReturn(vector()).when(parser).embed(any(),anyString(),anyLong(),anyString());try(var bridge=startBridge(python)){doAnswer(call->bridge.client().index(call.getArgument(0),call.getArgument(1),call.getArgument(2))).when(parser).index(any(),anyString(),anyMap());tasks.execute(101,task);assertThat(tasks.get(actor,task)).as(tasks.get(actor,task).toString()).containsEntry("status","SUCCEEDED");String generation=task.toString().replace("-","");assertThat(images.indexContent(actor,generation).bytes().length).isGreaterThan(384*4);assertThat(images.gallery(actor).get("status")).isEqualTo("READY");}}

    @Test void isolatedFeatureDockerPublishesAndReadsPrivateProductPhotos()throws Exception{String image=System.getProperty("jxc.test.purchase-image");Assumptions.assumeTrue(image!=null,"显式构建M3镜像后执行照片HTTP验收");var b=confirmedPhoto();try(var app=featureContainer(image,false)){app.start();String root="http://"+app.getHost()+":"+app.getMappedPort(8080)+"/api/v1";var http=java.net.http.HttpClient.newHttpClient();var body=Map.of("version",rows(b).getFirst().get("version"),"confirmOwnership",true,"imageIds",List.of(imageId(b)));var request=java.net.http.HttpRequest.newBuilder(java.net.URI.create(root+"/pur/order-imports/"+id(b)+"/rows/"+rowId(b)+"/photos")).header("Authorization","Bearer purchase-import-source-test").header("X-Country-Id","101").header("Content-Type","application/json").header("Idempotency-Key",UUID.randomUUID().toString()).POST(java.net.http.HttpRequest.BodyPublishers.ofString(codec.write(body))).build();var response=http.send(request,java.net.http.HttpResponse.BodyHandlers.ofString());assertThat(response.statusCode()).as(response.body()).isEqualTo(200);assertThat(response.body()).contains("IMAGE_PUBLISH");var galleryRequest=java.net.http.HttpRequest.newBuilder(java.net.URI.create(root+"/pur/order-imports/gallery/status")).header("Authorization","Bearer purchase-import-source-test").header("X-Country-Id","101").GET().build();var galleryResponse=http.send(galleryRequest,java.net.http.HttpResponse.BodyHandlers.ofString());assertThat(galleryResponse.statusCode()).isEqualTo(200);assertThat(galleryResponse.body()).contains("NOT_READY","eligiblePhotos");assertThat(http.send(request,java.net.http.HttpResponse.BodyHandlers.ofString()).statusCode()).isEqualTo(200);long photo=owner.queryForObject("SELECT id FROM md_product_image",Long.class);var content=java.net.http.HttpRequest.newBuilder(java.net.URI.create(root+"/md/product-images/"+photo+"/content")).header("Authorization","Bearer purchase-import-source-test").header("X-Country-Id","101").GET().build();var bytes=http.send(content,java.net.http.HttpResponse.BodyHandlers.ofByteArray());assertThat(bytes.statusCode()).isEqualTo(200);assertThat(bytes.headers().firstValue("content-type").orElseThrow()).startsWith("image/png");assertThat(bytes.body()).isNotEmpty();assertThat(owner.queryForObject("SELECT count(*) FROM md_product_image",Integer.class)).isEqualTo(1);assertThat(owner.queryForObject("SELECT count(*) FROM image_feature",Integer.class)).isEqualTo(1);String expected=com.hs.jxc.attachment.AttachmentObjectStore.sha256(java.nio.file.Files.readAllBytes(java.nio.file.Path.of("target/jxc-app-0.1.0-SNAPSHOT.jar")));assertThat(app.execInContainer("sha256sum","/app/app.jar").getStdout()).startsWith(expected+" ");}}

    @Test void expiredIndexLeaseCannotPublishOrOverwriteTheNewOwner(){var b=confirmedPhoto();var published=publish(b,UUID.randomUUID().toString());UUID task=UUID.fromString(((List<?>)published.get("taskIds")).getFirst().toString());doReturn(vector()).when(parser).embed(any(),anyString(),anyLong(),anyString());doAnswer(call->{owner.update("UPDATE pur_order_import_task SET lease_owner=?,lease_until=clock_timestamp()+interval '1 minute' WHERE id=?",UUID.randomUUID(),task);return indexResult(call.getArgument(2));}).when(parser).index(any(),anyString(),anyMap());tasks.execute(101,task);assertThat(tasks.get(actor,task)).containsEntry("status","RUNNING");assertThat(owner.queryForObject("SELECT count(*) FROM md_image_index_generation WHERE status='READY'",Integer.class)).isZero();assertThat(images.list(actor,501).getFirst()).containsEntry("featureStatus","READY");owner.update("UPDATE pur_order_import_task SET lease_until=clock_timestamp()-interval '1 second' WHERE id=?",task);doAnswer(call->indexResult(call.getArgument(2))).when(parser).index(any(),anyString(),anyMap());tasks.execute(101,task);assertThat(tasks.get(actor,task)).containsEntry("status","SUCCEEDED");verify(parser,times(1)).embed(any(),anyString(),anyLong(),anyString());}

    @Test void photosOfDisabledCountryProductsAreNotMisreportedAsAnEmptyGallery(){var b=confirmedPhoto();var published=publish(b,UUID.randomUUID().toString());UUID task=UUID.fromString(((List<?>)published.get("taskIds")).getFirst().toString());owner.update("UPDATE md_country_sku SET status='DISABLED',version=version+1 WHERE country_id=101 AND product_id=501");var before=images.gallery(actor);assertThat(before.get("status")).isEqualTo("NOT_READY");assertThat(((Map<?,?>)before.get("coverage")).get("photos")).isEqualTo(1);assertThat(((Map<?,?>)before.get("coverage")).get("eligiblePhotos")).isEqualTo(0);doReturn(vector()).when(parser).embed(any(),anyString(),anyLong(),anyString());tasks.execute(101,task);assertThat(tasks.get(actor,task)).containsEntry("errorCode","GALLERY_NO_READY_FEATURES");assertThat(images.list(actor,501).getFirst()).containsEntry("featureStatus","READY");owner.update("UPDATE md_country_sku SET status='ENABLED',version=version+1 WHERE country_id=101 AND product_id=501");tasks.retry(actor,task,UUID.randomUUID().toString(),null);doAnswer(call->indexResult(call.getArgument(2))).when(parser).index(any(),anyString(),anyMap());tasks.execute(101,task);assertThat(images.gallery(actor).get("status")).isEqualTo("READY");verify(parser,times(1)).embed(any(),anyString(),anyLong(),anyString());}

    @Test void galleryRebuildFillsMissingFeaturesAfterTheSourceRowHasChanged(){var b=confirmedPhoto();publish(b,UUID.randomUUID().toString());owner.update("UPDATE pur_order_import_task SET status='STALE' WHERE kind='IMAGE_PUBLISH'");imports.saveRow(actor,id(b),rowId(b),Map.of("version",3,"values",values()));var created=photos.rebuild(actor,id(b),UUID.randomUUID().toString());UUID task=UUID.fromString(created.get("id").toString());doAnswer(call->{long asset=call.getArgument(2);String credential=call.getArgument(1);assertThat(tasks.taskAsset(task,asset,credential).bytes()).isNotEmpty();assertThatThrownBy(()->tasks.taskAsset(task,asset+1,credential)).isInstanceOf(ApiException.class).extracting("status").isEqualTo(403);return vector();}).when(parser).embed(any(),anyString(),anyLong(),anyString());doAnswer(call->indexResult(call.getArgument(2))).when(parser).index(any(),anyString(),anyMap());tasks.execute(101,task);assertThat(tasks.get(actor,task)).as(tasks.get(actor,task).toString()).containsEntry("status","SUCCEEDED");assertThat(images.gallery(actor).get("status")).isEqualTo("READY");assertThat(rows(imports.get(actor,id(b))).getFirst()).containsEntry("decision","UNRESOLVED").containsEntry("readiness","UNRESOLVED");assertThat(owner.queryForObject("SELECT count(*) FROM md_product_image",Integer.class)).isEqualTo(1);assertThat(owner.queryForObject("SELECT count(*) FROM image_feature",Integer.class)).isEqualTo(1);}


    @SuppressWarnings("unchecked") @Test void aFailedNewPhotoLeavesThePublishedIndexAvailableWithExplicitPartialCoverage(){var first=confirmedPhoto();var published=publish(first,UUID.randomUUID().toString());doReturn(vector()).when(parser).embed(any(),anyString(),anyLong(),anyString());doAnswer(call->indexResult(call.getArgument(2))).when(parser).index(any(),anyString(),anyMap());UUID original=UUID.fromString(((List<?>)published.get("taskIds")).getFirst().toString());tasks.execute(101,original);var doc=photoDocument();var image=new LinkedHashMap<>(((List<Map<String,Object>>)doc.get("images")).getFirst());byte[] bytes=Base64.getDecoder().decode(image.get("contentBase64").toString());bytes=Arrays.copyOf(bytes,bytes.length+1);String hash=com.hs.jxc.attachment.AttachmentObjectStore.sha256(bytes);image.put("imageId",hash);image.put("sha256",hash);image.put("bytes",bytes.length);image.put("contentBase64",Base64.getEncoder().encodeToString(bytes));doc.put("images",List.of(image));var association=new LinkedHashMap<>(((List<Map<String,Object>>)doc.get("associations")).getFirst());association.put("imageId",hash);doc.put("associations",List.of(association));var second=confirmedPhoto(doc);var another=publish(second,UUID.randomUUID().toString());doThrow(new ApiException(503,"MODEL_UNAVAILABLE","新照片特征失败，旧图库保留")).when(parser).embed(any(),anyString(),anyLong(),anyString());tasks.execute(101,UUID.fromString(((List<?>)another.get("taskIds")).getFirst().toString()));var gallery=images.gallery(actor);assertThat(gallery).containsEntry("status","PARTIAL");assertThat((Map<String,Object>)gallery.get("coverage")).containsEntry("photos",2);assertThat(((Number)((Map<?,?>)gallery.get("coverage")).get("readyPhotos")).longValue()).isEqualTo(1);assertThat((Map<String,Object>)gallery.get("manifest")).containsEntry("generation",original.toString().replace("-",""));assertThat(owner.queryForObject("SELECT count(*) FROM md_image_index_generation WHERE active",Integer.class)).isEqualTo(1);}
}
